@startuml
class Person {
  +personID : string
  +phoneNumber : string
  +keywords : string[]
}

class ResearchInstitution {
  +institutionCode : string
}

class ScientificArticle {
  +DOI : string
  +title : string
}

class PeerReviewedPaper extends ScientificArticle {
  +citationCount : int
}

class TechnicalReport extends ScientificArticle {
}

class AuthorPosition {
  +position : string
}

class Publisher {
  +name : string
}

class Journal {
  +name : string
  +impactFactor : float
}

Person "1" -- "1" ResearchInstitution : works for
Person "0..*" -- "0..*" ScientificArticle : authors
Person "0..*" -- "0..*" PeerReviewedPaper : reviews

ScientificArticle "1" -- "*" AuthorPosition : has
Person "1" -- "*" AuthorPosition : in position

ResearchInstitution "1" -- "*" TechnicalReport : publishes
Publisher "1" -- "*" Journal : publishes
ResearchInstitution "0..*" -- "0..*" Journal : subscribes
Journal "1" -- "*" PeerReviewedPaper : publishes
@enduml

